// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

@Timeout(30)
class LmdbNoneIsolationReadTest {

	private static final String NAMESPACE = "urn:none-read:";
	private static final IRI SUBJECT = SimpleValueFactory.getInstance().createIRI(NAMESPACE, "subject");
	private static final IRI PREDICATE = SimpleValueFactory.getInstance().createIRI(NAMESPACE, "predicate");
	private static final IRI OBJECT = SimpleValueFactory.getInstance().createIRI(NAMESPACE, "object");
	private static final IRI CONTEXT = SimpleValueFactory.getInstance().createIRI(NAMESPACE, "context");

	@TempDir
	File directory;

	private LmdbStore store;
	private SailRepository repository;

	@BeforeEach
	void setUp() {
		store = new LmdbStore(directory);
		repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.setNamespace("test", NAMESPACE);
			connection.add(SUBJECT, PREDICATE, OBJECT, CONTEXT);
			connection.commit();
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void namespaceReadWhileAnotherNoneTransactionIsActive() {
		try (RepositoryConnection upload = repository.getConnection();
				RepositoryConnection reader = repository.getConnection()) {
			upload.begin(IsolationLevels.NONE);
			assertTrue(store.isIsolationDisabled());
			assertEquals(NAMESPACE, reader.getNamespace("test"));
			assertTrue(upload.isActive(), "A read on another connection must not end the upload transaction");
			upload.rollback();
			assertFalse(store.isIsolationDisabled());
			assertEquals(NAMESPACE, reader.getNamespace("test"));
		}
	}

	@Test
	void autoCommitReadsWhileAnotherNoneTransactionIsActive() {
		try (RepositoryConnection upload = repository.getConnection();
				RepositoryConnection reader = repository.getConnection()) {
			upload.begin(IsolationLevels.NONE);
			try (var namespaces = reader.getNamespaces()) {
				assertTrue(namespaces.stream()
						.anyMatch(namespace -> namespace.getPrefix().equals("test")
								&& namespace.getName().equals(NAMESPACE)));
			}
			for (boolean includeInferred : new boolean[] { false, true }) {
				try (var statements = reader.getStatements(SUBJECT, PREDICATE, OBJECT, includeInferred, CONTEXT)) {
					assertTrue(statements.hasNext());
					assertEquals(CONTEXT, statements.next().getContext());
					assertFalse(statements.hasNext());
				}
				assertTrue(reader.hasStatement(SUBJECT, PREDICATE, OBJECT, includeInferred, CONTEXT));
			}
			try (var contexts = reader.getContextIDs()) {
				assertEquals(CONTEXT, contexts.next());
				assertFalse(contexts.hasNext());
			}
			assertEquals(1, reader.size());
			upload.rollback();
			assertFalse(store.isIsolationDisabled());
			assertEquals(1, reader.size());
		}
	}
}
